BEGIN TRANSACTION;

-- COMPENSATING migration for data_20260802215744.
--
-- That migration resolved citation_mining rows to a source using global_ref_id
-- alone. global_ref_id is NULL in 146 of 183 rows, but 145 of those resolve
-- perfectly well through source_slug_links(slug, local_ref_id) — which is
-- citation_mining's own primary key. The result: 80 sources carried
-- citation_mining_status='pending' while holding a non-deferred mining row,
-- and the reported Tier 1-2 backlog was overstated by 25 sources.
--
-- Fix-forward per the immutability rule; the original migration is committed
-- and is not edited. 130 sources are corrected.
--
-- Resolution order matters: a source with ANY non-deferred mining row is
-- 'mined'; only if every resolving row is deferred is it 'deferred'.

UPDATE evidence_sources SET citation_mining_status='mined'
WHERE ref_id IN (
  SELECT COALESCE(m.global_ref_id, l.ref_id)
  FROM citation_mining m
  LEFT JOIN source_slug_links l ON l.slug = m.slug AND l.local_ref_id = m.local_ref_id
  WHERE COALESCE(m.deferred_reason,'') = ''
    AND COALESCE(m.global_ref_id, l.ref_id) IS NOT NULL
);

UPDATE evidence_sources SET citation_mining_status='deferred'
WHERE citation_mining_status <> 'mined'
  AND ref_id IN (
  SELECT COALESCE(m.global_ref_id, l.ref_id)
  FROM citation_mining m
  LEFT JOIN source_slug_links l ON l.slug = m.slug AND l.local_ref_id = m.local_ref_id
  WHERE COALESCE(m.deferred_reason,'') <> ''
    AND COALESCE(m.global_ref_id, l.ref_id) IS NOT NULL
);

COMMIT;
